UPDATE `god2`.`quest_content_profiles` SET `RewardTextZhTw`='哼！沒用的廢物！\\n連這點小小的攻擊都承受不了，以後要怎麼跟大爺我出去混啊？\\n再來再來！\\n還是說你想要放棄了？\\n把你奴才的能力都展現給本大爺我看看吧！\\p本大爺現在特別恩準你和本大爺單挑，把你後面跟著的那群狗同伴們打發掉吧。\\n否則你可別想得到本爺的神靈啊！' WHERE `ProfileId`='590becdf5e0d80706b96db1bd9c6501ffdf4f88c22f9d281458c7aa53401216f' AND `RewardTextZhTw`='哼！沒用的廢物！\\n連這點小小的攻擊都承受不了，以後要怎麼跟大爺我出去混啊？\\n再來再來！\\n還是說你想要放棄了？\\n把你奴才的能力都展現給本大爺我看看吧！\\p本大爺現在特別恩准你和本大爺單挑，把你後面跟著的那群狗同伴們打發掉吧。\\n否則你可別想得到本爺的神靈啊！';
